import java.util.*;
import java.nio.file.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path path = Path.of("quotes.txt");
        // 이번 파일 형식은 번호:한 줄 글이에요.
        Files.writeString(path, "1:시작\n2:다음\n");
        Map<Integer, String> loaded = new LinkedHashMap<>();
        System.out.println(loaded.size());
        for (String line : Files.readAllLines(path)) {
            String[] parts = line.split(":", 2);
            loaded.put(Integer.parseInt(parts[0]), parts[1]);
        }
        System.out.println(loaded.get(1));
    }
}

import java.util.*;
import java.nio.file.*;
interface QuoteStore { String load() throws Exception; }
class MemoryStore implements QuoteStore {
    public String load() { return "시작"; }
}
class FileStore implements QuoteStore {
    public String load() throws Exception { return Files.readString(Path.of("quotes.txt")); }
}
class QuoteService {
    // 서비스는 실제 저장 위치 대신 저장 역할을 받아요.
    private final QuoteStore store;
    QuoteService(QuoteStore store) { this.store = store; }
    String show() throws Exception { return store.load(); }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Files.writeString(Path.of("quotes.txt"), "시작");
        System.out.println(new QuoteService(new MemoryStore()).show());
        System.out.println(new QuoteService(new FileStore()).show());
    }
}

