import java.util.*;
import java.nio.file.*;


public class Main {
    public static void main(String[] args) throws Exception {
        Map<Integer, String> quotes = new LinkedHashMap<>();
        quotes.put(1, "시작");
        quotes.put(2, "다음");
        int targetId = 2;
        String message = "수정";
        // 존재하는 요청 대상만 바꿔야 해요.
        if (quotes.containsKey(targetId)) quotes.put(targetId, message);
        System.out.println(quotes);
    }
}
